#include "geometry_library.hpp"
#include <cmath>
vector<int> compressPeriod(const vector<int>&old,int H,mt19937&rng){vector<int> p(H);int common=rng()%old.size();for(int e=0;e<6;e++){vector<int> ops,times;for(int t=0;t<(int)old.size();t++){int op=(old[t]>>(2*e))&3;if(op){ops.push_back(op);times.push_back(t);}}while((int)ops.size()>H){vector<int> cuts;for(int j=0;j+1<(int)ops.size();j++)if((ops[j]==1&&ops[j+1]==2)||(ops[j]==2&&ops[j+1]==1)||(ops[j]==3&&ops[j+1]==3))cuts.push_back(j);if(cuts.empty())return {};int j=cuts[rng()%cuts.size()];ops.erase(ops.begin()+j,ops.begin()+j+2);}int prev=-1,cut=(rng()%4?common:rng()%old.size());for(int j=0;j<(int)ops.size();j++){int ideal=times.size()==ops.size()?times[j]-(times[j]>=cut):j*H/max(1,(int)ops.size());int t=max(prev+1,min(H-(int)ops.size()+j,ideal));p[t]|=ops[j]<<(2*e);prev=t;}}return p;}
struct CycleEval{vector<Node> states;int cost=0;int last=0;};
CycleEval cycleEval(const vector<int>&p,U root){CycleEval z;Node s;s.pose=root;z.states.push_back(s);for(int t=0;t<(int)p.size();t++){int old=s.made;s=step(s,p[t]);if(s.made>old)z.last=t+1;z.states.push_back(s);}if(s.made==C&&z.last==(int)p.size()&&canonical(s.pose)==canonical(root)){z.cost=0;return z;}if(s.made>=C)z.cost=10+32*abs(s.made-C)+(int)p.size()-z.last+pc(s.m&(T|F));else z.cost=48*max(0,C-s.made-1)+2*pc(T&~s.m)+3*pc(F&s.m);z.cost+=6*pdist(s.pose,root);return z;}
int db(int a,int b){int d=abs((a&127)-(b&127));return min(d,L-d)+int((a&128)!=(b&128));}
void emitterBridge(vector<int>&p,int e,int lo,int hi,int a,int b,mt19937&rng){for(int t=lo;t<hi;t++){vector<int> opts;for(int op=0;op<4;op++)if(db(moveByte[e][a][op],b)<=hi-t-1)opts.push_back(op);if(opts.empty())return;int old=(p[t]>>(2*e))&3,op=opts[rng()%opts.size()];if(rng()%3&&find(opts.begin(),opts.end(),old)!=opts.end())op=old;p[t]=(p[t]&~(3<<(2*e)))|(op<<(2*e));a=moveByte[e][a][op];}}
void chordMutation(vector<int>&p,const CycleEval&ev,mt19937&rng){int H=p.size();Node end=ev.states.back();U missing=T&~end.m,bad=F&end.m;bool erase=bad&&(missing==0||rng()%3==0);U cells=erase?bad:missing;if(!cells)return;int n=rng()%pc(cells),cell=0;for(U m=cells;m;m&=m-1){int k=__popcnt64((m&-m)-1);if(n--==0){cell=k;break;}}int tick=1+rng()%H,rad=1+rng()%min(H,6),lo=max(0,tick-rad),hi=min(H,tick+rad);vector<pair<int,int>> opts;for(int e=0;e<6;e++)for(int q=0;q<L;q++)if((rays[q][e].b[0]>>cell)&1){int a=(ev.states[lo].pose>>(8*e))&255,b=(ev.states[hi].pose>>(8*e))&255;if(db(a,q+128)<=tick-lo&&db(q+128,b)<=hi-tick)opts.push_back({e,q+128});}shuffle(opts.begin(),opts.end(),rng);vector<pair<int,int>> chosen;for(auto z:opts){bool dup=false;for(auto x:chosen)dup|=x.first==z.first;if(!dup)chosen.push_back(z);if(chosen.size()==size_t(erase?3:2))break;}if(chosen.size()<size_t(erase?3:2))return;for(auto[e,q]:chosen){int a=(ev.states[lo].pose>>(8*e))&255,b=(ev.states[hi].pose>>(8*e))&255;emitterBridge(p,e,lo,tick,a,q,rng);emitterBridge(p,e,tick,hi,q,b,rng);}}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int oldn,budget,freeRoot;while(cin>>R>>C>>oldn>>budget>>seed0>>freeRoot){vector<string> rows(2*R+1);for(auto&s:rows)cin>>s;U start;cin>>start;vector<int> old(oldn);for(int&a:old)cin>>a;init_geometry(rows,seed0%7);T=target.b[0];F=forbid.b[0];for(int e=0;e<6;e++)for(int a=0;a<2;a++)for(int p=0;p<L;p++){int b=p+128*a;rayByte[e][b]=a?rays[p][e].b[0]:0;moveByte[e][b]={b,(p+L-1)%L+128*a,(p+1)%L+128*a,p+128*(1-a)};}auto begin=Clock::now(),stop=begin+chrono::milliseconds(budget);mt19937 rng(seed0);int H=oldn-1,bestCost=100000;long long evals=0;vector<int> answer;U answerRoot=start;int aliasMask=0;Node end;end.pose=start;for(int a:old)end=step(end,a);for(int mask=0;mask<8;mask++)if(transformPose(start,mask)==end.pose){aliasMask=mask;break;}
 while(Clock::now()<stop&&answer.empty()){
  auto p=compressPeriod(old,H,rng);if(p.empty())break;U root=start;auto ev=cycleEval(p,root);evals++;double maxTemp=1.4;
  for(int it=0;it<16000&&Clock::now()<stop;it++){
   if(ev.cost==0){answer=p;answerRoot=root;break;}auto trial=p;U qr=root;int mode=rng()%16;
   if(mode<3&&freeRoot){int e=rng()%6,delta=rng()%2?1:-1;bool flip=rng()%5==0;int v=(qr>>(8*e))&255,b=((v&127)+delta+L)%L+(v&128);if(flip)b^=128;qr=(qr&~(255ULL<<(8*e)))|(U(b)<<(8*e));int axis=e%3;if(aliasMask>>axis&1){int j=(e+3)%6,v2=(qr>>(8*j))&255,b2=((v2&127)-delta+L)%L+(v2&128);if(flip)b2^=128;qr=(qr&~(255ULL<<(8*j)))|(U(b2)<<(8*j));}}
   else if(mode<6)chordMutation(trial,ev,rng);
   else{int e=rng()%6,a=rng()%H,b=(rng()%8==0)?rng()%H:(a+1+rng()%3)%H;if(a==b)continue;int x=(trial[a]>>(2*e))&3,y=(trial[b]>>(2*e))&3,nx=y,ny=x;if(mode==6&&x==0&&y==0){nx=1+rng()%3;ny=nx==3?3:3-nx;}else if(mode==7&&((x==1&&y==2)||(x==2&&y==1)||(x==3&&y==3)))nx=ny=0;else if(mode==8){auto d=[](int op){return op==1?-1:op==2?1:0;};vector<pair<int,int>> opts;for(int xx=0;xx<4;xx++)for(int yy=0;yy<4;yy++)if(d(xx)+d(yy)==d(x)+d(y)&&((xx==3)^(yy==3))==((x==3)^(y==3)))opts.push_back({xx,yy});auto z=opts[rng()%opts.size()];nx=z.first;ny=z.second;}trial[a]=(trial[a]&~(3<<(2*e)))|(nx<<(2*e));trial[b]=(trial[b]&~(3<<(2*e)))|(ny<<(2*e));}
   auto next=cycleEval(trial,qr);evals++;double temp=.06+maxTemp*(1.-double(it%4000)/4000.);if(next.cost<=ev.cost||double(rng())/4294967296.<exp((ev.cost-next.cost)/temp)){p=move(trial);root=qr;ev=move(next);}bestCost=min(bestCost,ev.cost);
  }
 }
 auto ms=chrono::duration_cast<chrono::milliseconds>(Clock::now()-begin).count();cout<<answer.size()<<' '<<bestCost<<' '<<ms<<' '<<answerRoot<<' '<<evals;for(int a:answer)cout<<' '<<a;cout<<'\n'<<flush;
 }}
